package edu.alliance.medislot.servlet;import edu.alliance.medislot.dao.DoctorDao;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;@WebServlet("/api/doctors")public class DoctorServlet extends JsonServlet{protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{try{send(r,200,new DoctorDao().all());}catch(Exception e){error(r,500,"Unable to load doctors.");}}}